import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Ctx, Limit, Mood, PopupView, Thread, UsageReport, WindowReport } from '../types'
import { DONE_SECONDS, SCENE_HEIGHT, SCENE_WIDTH, sceneSvg } from './scene'
import { parseLine, parseLines, READ_LIMIT, SLICE_MS, summarize } from './usage'
import type { FileSummary, Listed, WindowSpec } from './usage'

const mood = atom({ plugin: 'pixel-buddy', key: 'mood' } as const, 'idle' as Mood)
const moodAt = atom({ plugin: 'pixel-buddy', key: 'moodAt' } as const, 0)
const frame = atom({ plugin: 'pixel-buddy', key: 'frame' } as const, 0)
const cacheAt = atom({ plugin: 'pixel-buddy', key: 'cacheAt' } as const, null as number | null)
const now = atom({ plugin: 'pixel-buddy', key: 'now' } as const, 0)
const minute = atom({ plugin: 'pixel-buddy', key: 'minute' } as const, 0)
const ctx = atom({ plugin: 'pixel-buddy', key: 'ctx' } as const, null as Ctx | null)
const limits = atom({ plugin: 'pixel-buddy', key: 'limits' } as const, [] as Limit[])
const isPinned = atom({ plugin: 'pixel-buddy', key: 'isPinned' } as const, false)
const view = atom({ plugin: 'pixel-buddy', key: 'view' } as const, { window: 'five_hour', group: 'threads' } as PopupView)

// The "task complete" party plays once, then Claude relaxes for a while before idling.
const RELAX_MS = 4 * 60_000

// Transcripts are re-priced this often; a finished turn or Refresh asks sooner.
const SCAN_MS = 60_000
const WINDOW_MS = { five_hour: 5 * 3_600_000, seven_day: 7 * 86_400_000 } as const
// The hover group joining the info icon and the usage card it reveals.
const USAGE_SCOPE = 'pixel-buddy-usage'

const GREEN = '#4cc35a'
const AMBER = '#e5a33a'
const RED = '#e5534b'
const levelColor = (p: number) => (p >= 90 ? RED : p >= 70 ? AMBER : GREEN)

function span(ms: number): string {
  const m = Math.max(0, Math.round(ms / 60_000))
  const d = Math.floor(m / 1440)
  const h = Math.floor((m % 1440) / 60)
  if (d) return `${d}d ${h}h`
  if (h) return `${h}h ${m % 60}m`
  return `${m}m`
}

function clockText(ms: number): string {
  const s = Math.max(0, Math.ceil(ms / 1000))
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`
}

function ringSvg(percent: number, icon: 'clock' | 'cal'): string {
  const C = 2 * Math.PI * 12
  const p = Math.min(100, Math.max(0, percent)) / 100
  const glyph =
    icon === 'clock'
      ? '<circle cx="15" cy="15" r="5.5" fill="none" stroke="#a0a0a0" stroke-width="1.6"/><path d="M15 12v3.4h2.6" fill="none" stroke="#a0a0a0" stroke-width="1.6" stroke-linecap="round"/>'
      : '<rect x="10" y="11" width="10" height="9" rx="1.5" fill="none" stroke="#a0a0a0" stroke-width="1.6"/><path d="M10 14h10M12.5 9.5v3M17.5 9.5v3" stroke="#a0a0a0" stroke-width="1.6" stroke-linecap="round"/>'
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 30 30" width="30" height="30">` +
    `<circle cx="15" cy="15" r="12" fill="none" stroke="#3a3a3a" stroke-width="2.6"/>` +
    (p > 0
      ? `<circle cx="15" cy="15" r="12" fill="none" stroke="${levelColor(percent)}" stroke-width="2.6" stroke-linecap="round" ` +
        `stroke-dasharray="${(C * p).toFixed(2)} ${C.toFixed(2)}" transform="rotate(-90 15 15)"/>`
      : '') +
    glyph +
    `</svg>`
  )
}

// A pixel hourglass: sand on top drains as the cache TTL runs out.
function hourglassSvg(frac: number): string {
  const sand = frac > 0 ? (frac > 0.2 ? GREEN : AMBER) : '#555'
  const frame = '#9a9a9a'
  let px = ''
  const r = (x: number, y: number, w: number, h: number, c: string) => {
    px += `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${c}"/>`
  }
  r(0, 0, 7, 1, frame)
  r(0, 8, 7, 1, frame)
  r(1, 1, 1, 2, frame); r(5, 1, 1, 2, frame); r(2, 3, 1, 1, frame); r(4, 3, 1, 1, frame)
  r(3, 4, 1, 1, frame)
  r(2, 5, 1, 1, frame); r(4, 5, 1, 1, frame); r(1, 6, 1, 2, frame); r(5, 6, 1, 2, frame)
  const top = Math.ceil(2 * frac)
  if (top > 0) r(2, 3 - top, 3, top, sand)
  r(2, 7, 3, 1, sand)
  if (frac < 1 && frac > 0) r(2, 6, 3, 1, sand)
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 7 9" width="14" height="18" shape-rendering="crispEdges">${px}</svg>`
}

function ctxBarSvg(percent: number): string {
  let px = ''
  const lit = Math.round(percent / 10)
  for (let i = 0; i < 10; i++) {
    px += `<rect x="${i * 4}" y="0" width="3" height="8" fill="${i < lit ? levelColor(percent) : '#3a3a3a'}"/>`
  }
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 39 8" width="39" height="8" shape-rendering="crispEdges">${px}</svg>`
}

async function setMood($: EngineInterface, m: Mood) {
  const t = await $.clock.now()
  await update($, moodAt, () => t)
  await update($, mood, () => m)
  await update($, frame, () => t)
  // The browser animates each scene; the band redraws only when the scene changes.
  if (m === 'done') {
    $.clock.after(DONE_SECONDS * 1000 + 50, () => void tickFrame($).catch(() => {}))
    $.clock.after(DONE_SECONDS * 1000 + RELAX_MS + 50, () => void tickFrame($).catch(() => {}))
  }
}

async function tickFrame($: EngineInterface) {
  const t = await $.clock.now()
  await update($, frame, () => t)
}

// Which scene shows `elapsed` seconds into a mood: done hands off to relax, relax to idle.
function sceneFor(m: Mood, elapsed: number): { mood: Mood; t: number } {
  const relaxS = RELAX_MS / 1000
  if (m === 'done') {
    if (elapsed < DONE_SECONDS) return { mood: 'done', t: elapsed }
    return sceneFor('relax', elapsed - DONE_SECONDS)
  }
  if (m === 'relax' && elapsed >= relaxS) return { mood: 'idle', t: elapsed - relaxS }
  return { mood: m, t: elapsed }
}

function money(usd: number): string {
  if (usd >= 100) return `$${Math.round(usd).toLocaleString('en-US')}`
  return `$${usd.toFixed(2)}`
}

function bigTokens(n: number): string {
  if (n >= 1_000_000_000) return `${(n / 1_000_000_000).toFixed(1)}B`
  if (n >= 1_000_000) return `${Math.round(n / 1_000_000)}M`
  return `${Math.round(n / 1000)}k`
}

const clip = (s: string, n: number) => (s.length > n ? `${s.slice(0, n - 1)}…` : s)

// Where each window began: its reset less its length, or a rolling window before a reading.
function windowSpecs(rl: Limit[], now: number): WindowSpec[] {
  return (['five_hour', 'seven_day'] as const).map(kind => {
    const at = rl.find(l => l.kind === kind)?.resetsAt
    const reset = at ? Date.parse(at) : NaN
    return { kind, start: Number.isFinite(reset) && reset > now ? reset - WINDOW_MS[kind] : now - WINDOW_MS[kind] }
  })
}

// Dollars per percent of the window, from what it has cost and how full it is.
function outlook(lim: Limit | undefined, w: WindowReport | undefined, now: number) {
  if (!lim || !w) return undefined
  const len = WINDOW_MS[lim.kind as keyof typeof WINDOW_MS] ?? 0
  const reset = lim.resetsAt ? Date.parse(lim.resetsAt) : NaN
  const left = Number.isFinite(reset) ? Math.max(0, reset - now) : undefined
  const perPct = lim.percentUsed >= 1 && w.usd > 0 ? w.usd / lim.percentUsed : undefined
  const elapsed = left === undefined || !len ? 0 : (len - left) / len
  return {
    left,
    perPct,
    toGo: perPct === undefined ? undefined : Math.max(0, 100 - lim.percentUsed) * perPct,
    atReset: elapsed > 0.02 ? Math.round(lim.percentUsed / elapsed) : undefined,
  }
}

function barSvg(percent: number): string {
  const p = Math.min(100, Math.max(0, percent))
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 8" width="400" height="8">` +
    `<rect x="0" y="0" width="400" height="8" rx="4" fill="#3a3a3a"/>` +
    (p > 0 ? `<rect x="0" y="0" width="${Math.max(8, p * 4).toFixed(1)}" height="8" rx="4" fill="${levelColor(p)}"/>` : '') +
    `</svg>`
  )
}

function byProject(threads: Thread[]): Thread[] {
  const out = new Map<string, Thread>()
  for (const t of threads) {
    const key = t.project || '(no project)'
    const p = out.get(key)
    if (!p) out.set(key, { ...t, id: key, title: key })
    else {
      p.usd += t.usd
      p.tokens += t.tokens
      p.firstAt = Math.min(p.firstAt, t.firstAt)
      p.lastAt = Math.max(p.lastAt, t.lastAt)
    }
  }
  return [...out.values()].sort((a, b) => b.usd - a.usd)
}

// The scan's own state: it lives as long as the module, so a reload re-reads once.
const files = new Map<string, FileSummary>()
let projectsDir: string | undefined
let host: string | undefined
let isRunning = false
let pending: string[] = []
let listing = new Map<string, Listed>()
let windows: WindowSpec[] = []

// The report the band and the usage card draw; written once each scan is whole.
const report = atom({ plugin: 'pixel-buddy', key: 'report' } as const, null as UsageReport | null)

async function resolveDir($: EngineInterface): Promise<string | undefined> {
  if (projectsDir) return projectsDir
  const stored = await $.store.get('projectsDir')
  if (typeof stored === 'string' && (await $.fs.exists(stored).catch(() => false))) return (projectsDir = stored)
  const isWin = /^[A-Za-z]:/.test(await $.session.cwd())
  const argv = isWin
    ? ['cmd', '/d', '/c', 'if defined CLAUDE_CONFIG_DIR (echo %CLAUDE_CONFIG_DIR%) else (echo %USERPROFILE%\\.claude)']
    : ['sh', '-c', 'printf "%s\\n" "${CLAUDE_CONFIG_DIR:-$HOME/.claude}"']
  const r = await $.process.run(argv, { timeoutMs: 5000 }).catch(() => undefined)
  const dir = r?.stdout.trim()
  if (!dir) return undefined
  return setProjectsDir($, `${dir}${isWin ? '\\' : '/'}projects`)
}

async function setProjectsDir($: EngineInterface, dir: string) {
  if (dir === projectsDir) return dir
  projectsDir = dir
  await $.store.set('projectsDir', dir)
  return dir
}

async function hostName($: EngineInterface) {
  if (host !== undefined) return host
  const r = await $.process.run(['hostname'], { timeoutMs: 5000 }).catch(() => undefined)
  host = r?.stdout.trim().split('.')[0] ?? ''
  return host
}

async function readWhole($: EngineInterface, path: string, size: number, f: FileSummary) {
  const seen = new Set<string>()
  const carry = { rest: '' }
  if (size <= READ_LIMIT) {
    parseLines(await $.fs.read(path), f, carry, seen)
  } else {
    const isWin = /^[A-Za-z]:/.test(path)
    const argv = isWin ? ['cmd', '/d', '/c', 'type', path] : ['cat', path]
    for await (const piece of $.process.spawn({ argv })) {
      if (piece.stream === 'stdout') parseLines(piece.text, f, carry, seen)
    }
  }
  parseLine(carry.rest, f, seen)
}

// Lists every transcript touched since `since`: each main session file, and the
// subagent transcripts under its folder, billed to that session.
async function listFiles($: EngineInterface, dir: string, since: number) {
  const sep = dir.includes('\\') ? '\\' : '/'
  const out: Listed[] = []
  const projects = await $.fs.list(dir).catch(() => [])
  for (const p of projects) {
    if (p.kind !== 'dir') continue
    const pdir = `${dir}${sep}${p.name}`
    const entries = await $.fs.list(pdir).catch(() => [])
    for (const e of entries) {
      if (e.kind !== 'file' || !e.name.endsWith('.jsonl') || e.mtimeMs < since) continue
      const session = e.name.slice(0, -6)
      out.push({ path: `${pdir}${sep}${e.name}`, size: e.size, mtimeMs: e.mtimeMs, session, isMain: true })
      if (!entries.some(x => x.kind === 'dir' && x.name === session)) continue
      const sdir = `${pdir}${sep}${session}${sep}subagents`
      for (const s of await $.fs.list(sdir).catch(() => [])) {
        if (s.kind !== 'file' || !s.name.endsWith('.jsonl') || s.mtimeMs < since) continue
        out.push({ path: `${sdir}${sep}${s.name}`, size: s.size, mtimeMs: s.mtimeMs, session, isMain: false })
      }
    }
  }
  return out
}

// The transcript a classic hook names is the surest way to the projects folder.
async function noteTranscript($: EngineInterface, transcriptPath: string | undefined) {
  if (!transcriptPath) return
  const cut = transcriptPath.split(/[\\/]/)
  if (cut.length < 3) return
  const sep = transcriptPath.includes('\\') ? '\\' : '/'
  await setProjectsDir($, cut.slice(0, -2).join(sep))
}

// Re-reads the transcripts that changed since the last scan, a slice per dispatch,
// and writes the report once the last file is in. Resolves true when that write is
// done or coming.
async function scan($: EngineInterface, specs: WindowSpec[]): Promise<boolean> {
  if (isRunning) return false
  isRunning = true
  let isHandedOff = false
  try {
    const dir = await resolveDir($)
    if (!dir) return false
    const now = await $.clock.now()
    windows = specs
    const listed = await listFiles($, dir, Math.min(...specs.map(w => w.start)))
    listing = new Map(listed.map(l => [l.path, l]))
    for (const path of files.keys()) if (!listing.has(path)) files.delete(path)
    pending = listed
      .filter(l => {
        const f = files.get(l.path)
        if (!f) return true
        if (f.size === l.size && f.mtimeMs === l.mtimeMs) return false
        // A big file still being written is re-read at most every five minutes.
        return l.size <= READ_LIMIT || now - f.parsedAt > 5 * 60_000
      })
      .sort((a, b) => b.mtimeMs - a.mtimeMs)
      .map(l => l.path)
    isHandedOff = await scanSlice($)
    return true
  } finally {
    if (!isHandedOff) isRunning = false
  }
}

// Resolves true when it handed the rest of the files to a later timer.
async function scanSlice($: EngineInterface): Promise<boolean> {
  const began = await $.clock.now()
  while (pending.length) {
    const path = pending.shift()!
    const l = listing.get(path)
    if (!l) continue
    const f: FileSummary = {
      size: l.size,
      mtimeMs: l.mtimeMs,
      parsedAt: began,
      session: l.session,
      isMain: l.isMain,
      entries: [],
      last: undefined,
    }
    try {
      await readWhole($, path, l.size, f)
      files.set(path, f)
    } catch {
      // Unreadable now (locked, vanished): keep what was there and retry next scan.
    }
    if ((await $.clock.now()) - began > SLICE_MS && pending.length) {
      $.clock.after(50, () => {
        scanSlice($).then(
          isLater => void (isLater || (isRunning = false)),
          () => void (isRunning = false),
        )
      })
      return true
    }
  }
  const t = await $.clock.now()
  const r = summarize(files, windows, t, await hostName($))
  // Written together, so the band redraws once for the new report and its clock.
  await update($, report, () => r)
  await update($, minute, () => t)
  return false
}

// Prices every transcript on the machine against the windows the limits name.
async function rescan($: EngineInterface): Promise<boolean> {
  return scan($, windowSpecs(await read($, limits), await $.clock.now()))
}

// The band's once-a-minute redraw: a rescan, which moves the clock when it writes the
// report; when no scan runs, the clock alone.
async function tickMinute($: EngineInterface) {
  const isWriting = await rescan($).catch(() => false)
  if (!isWriting) {
    const t = await $.clock.now()
    await update($, minute, () => t)
  }
}

const kTokens = (n: number) => (n >= 1_000_000 ? `${(n / 1_000_000).toFixed(1)}M` : `${Math.round(n / 1000)}k`)

export const register: Register = (on, options) => {
  const ttlMs = options.cacheTtl === '5m' ? 5 * 60_000 : 60 * 60_000

  on('session.start', async ($, e, next) => {
    const u = await $.session.usage()
    await update($, ctx, () => u.context)
    await update($, limits, () => u.rateLimits)
    const t0 = await $.clock.now()
    await update($, frame, () => t0)
    await update($, minute, () => t0)

    // Keep "resets in" and the prices fresh, and tick the cache countdown while it is
    // warm (only the model picker's row reads that one, so the band is left alone).
    await update($, moodAt, () => t0)
    $.clock.every(1_000, async () => {
      const at = await read($, cacheAt)
      if (at === null) return
      const t = await $.clock.now()
      if (t - at < ttlMs + 2_000) await update($, now, () => t)
    })

    // Price every transcript on the machine once the session is up, then keep it fresh.
    $.clock.after(1_500, () => void rescan($).catch(() => {}))
    $.clock.every(SCAN_MS, () => void tickMinute($).catch(() => {}))

    return next(e)
  })

  // A classic hook names this session's transcript, and so the folder they all live in.
  on('classic.SessionStart', async ($, e, next) => {
    await noteTranscript($, e.transcript_path).catch(() => {})
    return next(e)
  }).catch(($, e, next) => next(e))
  on('classic.UserPromptSubmit', async ($, e, next) => {
    await noteTranscript($, e.transcript_path).catch(() => {})
    return next(e)
  }).catch(($, e, next) => next(e))

  // Each response refreshes the prompt cache and reports the live usage.
  on('session.measure', async ($, e, next) => {
    await update($, ctx, () => e.context)
    // Only a changed reading is written: each write redraws the band.
    if (e.rateLimits.length && JSON.stringify(e.rateLimits) !== JSON.stringify(await read($, limits))) {
      await update($, limits, () => e.rateLimits)
    }
    if (e.changed.includes('context')) {
      const t = await $.clock.now()
      await update($, cacheAt, () => t)
      await update($, now, () => t)
    }
    return next(e)
  })

  on('turn.start', async ($, e, next) => {
    await setMood($, 'working')
    return next(e)
  })

  // Task complete: the party plays once, then Claude relaxes, then idles. The hand-offs
  // are worked out from the clock (see sceneFor); timers redraw the band at each one,
  // and the minute tick catches any a reload lost.
  on('turn.complete', async ($, e, next) => {
    if (e.agentId) return next(e)
    await setMood($, e.isAborted || e.reason === 'error' ? 'idle' : 'done')
    $.clock.after(2_000, () => void rescan($).catch(() => {}))
    return next(e)
  })

  // The band above the prompt: two usage rings on the left, the mascot on the right.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const ui = $.ui.resolve(e)
    const { Box, Text } = ui
    const rl = await read($, limits)
    const t = await read($, minute)
    const stored = await read($, mood)
    const m: Mood = e.props.isWorking ? 'working' : stored === 'working' ? 'idle' : stored
    // Read so the hand-off timers redraw the band; the scene itself is placed by the
    // clock, so a redraw (which reloads the drawing) picks the animation up mid-step.
    await read($, frame)
    const tNow = await $.clock.now()
    const since = m === stored ? await read($, moodAt) : tNow
    const { mood: shownMood, t: sceneT } = sceneFor(m, Math.max(0, (tNow - since) / 1000))
    const shown = [
      { kind: 'five_hour', label: '5h', icon: 'clock' as const },
      { kind: 'seven_day', label: '7d', icon: 'cal' as const },
    ].map(s => ({ ...s, lim: rl.find(l => l.kind === s.kind) }))

    const r = await read($, report)
    const caption = (lim: Limit | undefined, label: string) =>
      lim?.resetsAt && t ? `${label} · resets in ${span(Date.parse(lim.resetsAt) - t)}` : `${label} · waiting for a reading`
    const pctText = (lim: Limit | undefined) => (lim ? `${Math.round(lim.percentUsed)}%` : '–')
    const usdText = (kind: string) => {
      const w = r?.[kind as 'five_hour' | 'seven_day']
      return w ? money(w.usd) : undefined
    }

    if (e.surface !== 'desktop' && e.surface !== 'vscode') {
      return (
        <Box>
          <Text dimColor>
            {shown.map(s => [s.label, pctText(s.lim), usdText(s.kind)].filter(Boolean).join(' ')).join('   ')}
          </Text>
        </Box>
      )
    }
    const { Svg, Button, Select } = $.ui.resolve(e as typeof e & { surface: 'desktop' })
    const pinned = await read($, isPinned)
    const v = await read($, view)

    // The usage card: each window's outlook, then what spent it.
    const limitBlock = (kind: 'five_hour' | 'seven_day', title: string) => {
      const lim = rl.find(l => l.kind === kind)
      const o = outlook(lim, r?.[kind], t)
      const parts = [
        o?.left !== undefined ? `${span(o.left)} left` : undefined,
        o?.toGo !== undefined ? `≈${money(o.toGo)} to go` : r?.[kind] ? `${money(r[kind]!.usd)} spent` : undefined,
        o?.atReset !== undefined ? `~${o.atReset}% at reset` : undefined,
      ].filter(Boolean)
      return (
        <Box flexDirection="column">
          <Box flexDirection="row" justifyContent="space-between">
            <Text bold>{title}</Text>
            <Text bold color={lim ? levelColor(lim.percentUsed) : undefined}>{pctText(lim)}</Text>
          </Box>
          <Svg source={barSvg(lim?.percentUsed ?? 0)} alt={`${title} used`} />
          <Text dimColor>{parts.length ? parts.join(' · ') : 'waiting for a reading'}</Text>
        </Box>
      )
    }
    const w = r?.[v.window]
    const winLim = rl.find(l => l.kind === v.window)
    const perPct = outlook(winLim, w, t)?.perPct
    // The band shows the top `maxRows` rows and scrolls the rest: the meters row and
    // the card's fixed rows (about 16) come first, then two rows a thread.
    const fits = Math.floor((e.props.maxRows - 16) / 2)
    const rows = w ? (v.group === 'threads' ? w.threads : byProject(w.threads)).slice(0, Math.max(1, Math.min(6, fits))) : []
    const winLabel = v.window === 'five_hour' ? '5h' : '7d'
    const ago = r ? Math.max(0, Math.round((t - r.at) / 60_000)) : undefined
    const card = (
      <Box
        width={Math.max(30, Math.min(58, e.props.bodyColumns - 2))}
        marginTop={1}
        flexDirection="column"
        paddingX={2}
        borderStyle="round"
        borderColor="#3a3a3a"
        backgroundColor="#1c1c1c"
        // Shown while the icon or the card is hovered; a click on the icon pins it open.
        display={pinned ? 'flex' : 'none'}
        hover={pinned ? undefined : { scope: USAGE_SCOPE, display: 'flex' }}
      >
        <Box flexDirection="row" justifyContent="space-between" alignItems="center">
          <Text dimColor>Usage</Text>
          {pinned ? (
            <Button key="pb-close" label="✕" plain role="dismiss" onPress={() => update($, isPinned, () => false)} />
          ) : null}
        </Box>
        {limitBlock('five_hour', '5h limit')}
        {limitBlock('seven_day', '7d limit')}
        <Text>
          {r ? `Sessions: ${r.working} working · ${r.yourTurn} your turn` : 'Reading transcripts…'}
        </Text>
        <Box flexDirection="row" justifyContent="space-between" alignItems="center">
          <Box flexDirection="row" gap={1}>
            <Select
              key="pb-group"
              options={[
                { value: 'threads', label: 'Threads' },
                { value: 'projects', label: 'Projects' },
              ]}
              value={v.group}
              onSelect={g => update($, view, x => ({ ...x, group: g === 'projects' ? ('projects' as const) : ('threads' as const) }))}
            />
            <Select
              key="pb-window"
              options={[
                { value: 'five_hour', label: '5h window' },
                { value: 'seven_day', label: '7d window' },
              ]}
              value={v.window}
              onSelect={k => update($, view, x => ({ ...x, window: k === 'seven_day' ? ('seven_day' as const) : ('five_hour' as const) }))}
            />
          </Box>
          <Box flexDirection="row" gap={1} alignItems="center">
            <Text dimColor>{ago === undefined ? '' : ago === 0 ? 'now' : `${ago}m ago`}</Text>
            <Button key="pb-refresh" label="↻ Refresh" plain onPress={() => void rescan($).catch(() => {})} />
          </Box>
        </Box>
        <Box flexDirection="row" justifyContent="space-between">
          <Text dimColor bold>{`${v.group.toUpperCase()} · ${winLabel.toUpperCase()} WINDOW`}</Text>
          <Text bold>{w ? money(w.usd) : '–'}</Text>
        </Box>
        {rows.length ? (
          <Box flexDirection="column">
            {rows.map(th => (
              <Box key={`pb-${th.id}`} flexDirection="column">
                <Box flexDirection="row" justifyContent="space-between">
                  <Text>{clip(th.title.replace(/\s+/g, ' '), 44)}</Text>
                  <Text bold>{money(th.usd)}</Text>
                </Box>
                <Text dimColor>
                  {[
                    perPct ? `≈${(th.usd / perPct).toFixed(1)}%` : undefined,
                    `${bigTokens(th.tokens)} tok`,
                    span(Math.max(60_000, th.lastAt - th.firstAt)),
                    r?.host || undefined,
                    v.group === 'threads' ? th.project || undefined : undefined,
                  ]
                    .filter(Boolean)
                    .join(' · ')}
                </Text>
              </Box>
            ))}
          </Box>
        ) : (
          <Text dimColor>{r ? `Nothing spent in this ${winLabel} window yet` : 'Pricing every session on this machine…'}</Text>
        )}
        <Text dimColor>{"≈ API-rate cost of this machine's transcripts"}</Text>
      </Box>
    )

    // The card sits in the band's own flow below the meters (a placed Box would be
    // clipped to the band), so the band grows to hold it while it shows. Below, not
    // above: a band taller than its rows scrolls from the top, and a card above would
    // push the icon out from under the pointer, ending the hover that shows it.
    return (
      <Box flexDirection="column" paddingX={1}>
        <Box flexDirection="row" alignItems="center" justifyContent="space-between">
          <Box flexDirection="row" alignItems="center" gap={3}>
            {shown.map(s => (
              <Box key={s.kind} flexDirection="row" alignItems="center" gap={1}>
                <Svg source={ringSvg(s.lim?.percentUsed ?? 0, s.icon)} alt={`${s.label} usage ring`} width={30} height={30} />
                <Text bold>{pctText(s.lim)}</Text>
                {usdText(s.kind) ? <Text color={GREEN}>{usdText(s.kind)}</Text> : null}
                <Text dimColor>{caption(s.lim, s.label)}</Text>
              </Box>
            ))}
            <Box flexDirection="row" alignItems="center" hover={{ scope: USAGE_SCOPE }}>
              <Button key="pb-info" label="ⓘ" plain dimColor onPress={() => update($, isPinned, x => !x)} />
            </Box>
          </Box>
          <Svg
            source={sceneSvg(shownMood, sceneT)}
            isInteractive
            alt={`Claude is ${shownMood === 'done' ? 'celebrating' : shownMood === 'relax' ? 'relaxing' : shownMood}`}
            width={SCENE_WIDTH}
            height={SCENE_HEIGHT}
          />
        </Box>
        {card}
      </Box>
    )
  })

  // Beside the model picker: prompt-cache countdown and context fill.
  on('ui.render', { component: 'SessionMode' }, async ($, e, next) => {
    const { Box, Text } = $.ui.resolve(e)
    const at = await read($, cacheAt)
    const tNow = await read($, now)
    const c = await read($, ctx)
    const left = at === null ? 0 : ttlMs - (tNow - at)
    const warm = at !== null && left > 0
    const cacheLabel = at === null ? 'cache –' : warm ? `cache ${clockText(left)}` : 'cache cold'
    const cacheColor = !warm ? undefined : left < 60_000 ? AMBER : GREEN
    const pct = c?.percent
    const ctxLabel =
      pct === undefined ? 'ctx –' : `ctx ${pct}%${c?.tokens ? ` · ${kTokens(c.tokens)}/${kTokens(c.window)}` : ''}`
    const modes = e.props.modes.join(' & ')

    if (e.surface !== 'desktop' && e.surface !== 'vscode') {
      return <Text dimColor>{[cacheLabel, ctxLabel, modes].filter(Boolean).join('  ·  ')}</Text>
    }
    const { Svg } = $.ui.resolve(e as typeof e & { surface: 'desktop' })

    return (
      <Box flexDirection="row" alignItems="center" gap={1}>
        <Svg source={hourglassSvg(warm ? left / ttlMs : 0)} alt="prompt cache timer" width={14} height={18} />
        <Text color={cacheColor} dimColor={!warm}>{cacheLabel}</Text>
        <Text dimColor>·</Text>
        <Svg source={ctxBarSvg(pct ?? 0)} alt="context used" width={39} height={8} />
        <Text dimColor>{ctxLabel}</Text>
        {modes ? <Text dimColor>{`· ${modes}`}</Text> : null}
      </Box>
    )
  })
}

files.hooks/scene.ts:
// Pixel-art scenes for the mascot: every pixel is a <rect> in a 100x18 grid drawn at
// 3x, and the motion comes from keyframe tracks. `sceneSvg` hands the tracks to the
// browser as CSS animations, so the band need not redraw to animate (a redraw every
// frame resets the hover and press of everything else drawn in it); `sceneFrameSvg`
// evaluates them here into one still frame at time `t`.

import type { Mood } from '../types'

// The band's own color, painted behind the scene.
export const BAND_BG = '#212121'

const W = 100
const H = 18

const PAL: Record<string, string> = {
  o: '#d97757', // claude orange
  O: '#b65a3c', // orange shade
  e: '#1a1a1a', // eyes
  K: '#262626',
  k: '#121212',
  w: '#f4efe4',
  y: '#f7dc6f',
  Y: '#e8a33d',
  t: '#c9a46a',
  b: '#8a5a2b',
  B: '#5b3a1c',
  g: '#8a8a8a',
  G: '#4a4a4a',
  c: '#7fd6e8',
  C: '#9fd8f0',
  n: '#5fbf6a',
  N: '#2f7d3a',
  r: '#e5534b',
  R: '#a8322c',
  p: '#f08fb0',
  u: '#5a8fe6',
  U: '#2d4f9e',
  V: '#1b2c5c',
  l: '#c3c7cf',
  L: '#7d838c',
  P: '#efe8d6',
  s: '#3a2a52',
  m: '#7d3b63',
  d: '#d9673f',
  f: '#f2a14a',
  h: '#ffd27a',
  v: '#9b6be0',
}

const fill = (c: string) => PAL[c] ?? c
const rect = (x: number, y: number, w: number, h: number, c: string) =>
  `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${fill(c)}"/>`

// An ASCII sprite: one char per pixel, '.' is transparent; runs merge into one rect.
function spr(rows: string[], x = 0, y = 0): string {
  let out = ''
  rows.forEach((row, j) => {
    let i = 0
    while (i < row.length) {
      const c = row[i]
      if (c === '.' || c === ' ') {
        i++
        continue
      }
      let k = i
      while (k < row.length && row[k] === c) k++
      out += rect(x + i, y + j, k - i, 1, c)
      i = k
    }
  })
  return out
}

// Deterministic noise so the art is the same on every frame.
const rnd = (n: number) => {
  const s = Math.sin(n * 127.1 + 311.7) * 43758.5453
  return s - Math.floor(s)
}

// ---------- keyframe tracks ----------

type Pose = { tx?: number; ty?: number; o?: number; sx?: number; sy?: number }
type Track = [number, Pose][]
const BASE: Required<Pose> = { tx: 0, ty: 0, o: 1, sx: 1, sy: 1 }

const KF: Record<string, Track> = {
  bob: [[0, { ty: 0 }], [50, { ty: -1 }], [100, { ty: 0 }]],
  hop: [[0, { ty: 0 }], [50, { ty: -3 }], [100, { ty: 0 }]],
  wave: [[0, { ty: 0 }], [50, { ty: -2 }], [100, { ty: 0 }]],
  blink: [[0, { o: 1 }], [92, { o: 1 }], [94, { o: 0 }], [97, { o: 0 }], [100, { o: 1 }]],
  sweep: [[0, { tx: 0 }], [50, { tx: -2 }], [100, { tx: 0 }]],
  dust: [[0, { tx: 0, ty: 0, o: 1 }], [100, { tx: -9, ty: -3, o: 0 }]],
  tw: [[0, { o: 0 }], [30, { o: 1 }], [60, { o: 1 }], [100, { o: 0 }]],
  rise: [[0, { tx: 0, ty: 0, o: 0 }], [15, { o: 1 }], [100, { tx: 0, ty: -10, o: 0 }]],
  riseR: [[0, { tx: 0, ty: 0, o: 0 }], [15, { o: 1 }], [100, { tx: 4, ty: -9, o: 0 }]],
  walk: [[0, { tx: -36 }], [45, { tx: 0 }], [50, { tx: 0 }], [95, { tx: -36 }], [100, { tx: -36 }]],
  look: [[0, { tx: 1 }], [50, { tx: -1 }], [100, { tx: -1 }]],
  scan: [[0, { tx: -1 }], [50, { tx: 1 }], [100, { tx: -1 }]],
  grow: [[0, { sx: 0 }], [70, { sx: 1 }], [100, { sx: 1 }]],
  growY: [[0, { sy: 0 }], [60, { sy: 1 }], [100, { sy: 1 }]],
  pull: [[0, { ty: 9 }], [12, { ty: 0 }], [100, { ty: 0 }]],
  fly: [[0, { tx: 0, ty: 0, o: 1 }], [100, { tx: -14, ty: -12, o: 0 }]],
  dispatch: [[0, { tx: 0, o: 0 }], [6, { o: 1 }], [88, { o: 1 }], [100, { tx: -48, o: 0 }]],
  fall: [[0, { tx: 0, ty: -4 }], [50, { tx: 2, ty: 10 }], [100, { tx: -1, ty: 24 }]],
  dance: [
    [0, { tx: 0, ty: 0 }], [12, { tx: 0, ty: -4 }], [25, { tx: 0, ty: 0 }], [37, { tx: 0, ty: -4 }], [50, { tx: 0, ty: 0 }],
    [62, { tx: -2, ty: -1 }], [75, { tx: 2, ty: 0 }], [87, { tx: -2, ty: -1 }], [100, { tx: 0, ty: 0 }],
  ],
  sink: [[0, { ty: 0 }], [100, { ty: 3 }]],
  swing: [[0, { tx: -1 }], [50, { tx: 1 }], [100, { tx: -1 }]],
  on: [[0, { o: 1 }], [50, { o: 0 }], [100, { o: 0 }]],
  off: [[0, { o: 0 }], [50, { o: 1 }], [100, { o: 1 }]],
  leap: [
    [0, { tx: 0, ty: 0, o: 0 }], [78, { tx: 0, ty: 0, o: 0 }], [82, { tx: -2, ty: -4, o: 1 }],
    [88, { tx: -4, ty: -5, o: 1 }], [94, { tx: -6, ty: 0, o: 0 }], [100, { tx: 0, ty: 0, o: 0 }],
  ],
  drift: [[0, { tx: 0, ty: 0 }], [100, { tx: -70, ty: -2 }]],
  zoom: [[0, { tx: 0 }], [100, { tx: -72 }]],
  flip: [[0, { sx: 1 }], [60, { sx: 1 }], [70, { sx: 0.5 }], [80, { sx: -0.5 }], [90, { sx: -1 }], [100, { sx: -1 }]],
  carry: [[0, { tx: 0 }], [8, { tx: 0 }], [45, { tx: -22 }], [55, { tx: -22 }], [92, { tx: 0 }], [100, { tx: 0 }]],
  pace: [[0, { tx: 0 }], [50, { tx: -6 }], [100, { tx: 0 }]],
  magscan: [[0, { tx: 0, ty: 0 }], [25, { tx: -14, ty: -2 }], [50, { tx: -8, ty: 3 }], [75, { tx: -18, ty: 2 }], [100, { tx: 0, ty: 0 }]],
  dash: [[0, { tx: 0 }], [100, { tx: -8 }]],
  flipfood: [[0, { ty: 0 }], [70, { ty: 0 }], [80, { ty: -3 }], [90, { ty: -2 }], [100, { ty: 0 }]],
  vis2: [[0, { o: 1 }], [50, { o: 0 }], [100, { o: 0 }]],
}
const visTrack = (n: number): Track => [[0, { o: 1 }], [100 / n, { o: 0 }], [100, { o: 0 }]]

type Timing = { kind: 'step' } | { kind: 'linear' } | { kind: 'steps'; n: number }
type Anim = { track: Track; dur: number; delay: number; timing: Timing; count: number; fwd: boolean; back: boolean }

const animCache = new Map<string, Anim>()
// Reads a CSS-style shorthand: "bob 1s step-end infinite -0.5s", "fall 2s steps(12) 0.4s 2 both".
function parseAnim(def: string): Anim {
  const hit = animCache.get(def)
  if (hit) return hit
  const parts = def.trim().split(/\s+/)
  const name = parts[0]
  const track = KF[name] ?? (name.startsWith('vis') ? visTrack(Number(name.slice(3))) : [[0, {}], [100, {}]] as Track)
  const times: number[] = []
  let timing: Timing = { kind: 'linear' }
  let count = 1
  let fwd = false
  let back = false
  for (const p of parts.slice(1)) {
    if (/^-?[\d.]+s$/.test(p)) times.push(parseFloat(p))
    else if (p === 'step-end') timing = { kind: 'step' }
    else if (p === 'linear') timing = { kind: 'linear' }
    else if (p.startsWith('steps(')) timing = { kind: 'steps', n: parseInt(p.slice(6), 10) }
    else if (p === 'infinite') count = Infinity
    else if (/^\d+$/.test(p)) count = Number(p)
    else if (p === 'forwards') fwd = true
    else if (p === 'backwards') back = true
    else if (p === 'both') fwd = back = true
  }
  const a: Anim = { track, dur: times[0] ?? 1, delay: times[1] ?? 0, timing, count, fwd, back }
  animCache.set(def, a)
  return a
}

function sampleProp(track: Track, key: keyof Pose, pct: number, timing: Timing): number {
  const pts = track.filter(([, p]) => p[key] !== undefined).map(([at, p]) => [at, p[key] as number] as const)
  if (!pts.length) return BASE[key]
  if (pts[0][0] > 0) pts.unshift([0, BASE[key]])
  if (pts[pts.length - 1][0] < 100) pts.push([100, BASE[key]])
  for (let i = 0; i < pts.length - 1; i++) {
    const [a, va] = pts[i]
    const [b, vb] = pts[i + 1]
    if (pct >= a && pct < b) {
      let f = (pct - a) / (b - a)
      if (timing.kind === 'step') f = 0
      else if (timing.kind === 'steps') f = Math.floor(f * timing.n) / timing.n
      return va + (vb - va) * f
    }
  }
  return pts[pts.length - 1][1]
}

// The pose of an animation at time t, or null where it has no effect (before or after its run).
function poseAt(def: string, t: number): Required<Pose> | null {
  const a = parseAnim(def)
  const el = t - a.delay
  let pct: number
  if (el < 0) {
    if (!a.back) return null
    pct = 0
  } else if (el >= a.dur * a.count) {
    if (!a.fwd) return null
    pct = 100
  } else {
    pct = ((el % a.dur) / a.dur) * 100
  }
  const keys: (keyof Pose)[] = ['tx', 'ty', 'o', 'sx', 'sy']
  const out = { ...BASE }
  for (const k of keys) out[k] = pct === 100 ? lastValue(a.track, k) : sampleProp(a.track, k, pct, a.timing)
  return out
}
function lastValue(track: Track, key: keyof Pose): number {
  for (let i = track.length - 1; i >= 0; i--) if (track[i][1][key] !== undefined) return track[i][1][key] as number
  return BASE[key]
}

const n2 = (v: number) => Math.round(v * 100) / 100

// The tracks as CSS keyframes, each property interpolated as sampleProp does.
function keyframesCss(name: string, track: Track): string {
  const has = (k: keyof Pose) => track.some(([, p]) => p[k] !== undefined)
  const moves = has('tx') || has('ty') || has('sx') || has('sy')
  const stops = [...new Set([0, ...track.map(([at]) => at), 100])].sort((a, b) => a - b)
  const linear: Timing = { kind: 'linear' }
  const at = (k: keyof Pose, pct: number) =>
    n2(pct >= 100 ? lastValue(track, k) : sampleProp(track, k, pct, linear))
  const steps = stops.map(pct => {
    const decl: string[] = []
    if (moves) {
      decl.push(
        `transform:translate(${at('tx', pct)}px,${at('ty', pct)}px) scale(${at('sx', pct)},${at('sy', pct)})`,
      )
    }
    if (has('o')) decl.push(`opacity:${at('o', pct)}`)
    return `${pct}%{${decl.join(';')}}`
  })
  return `@keyframes ${name}{${steps.join('')}}`
}

// The shorthand with its delay (the second time in it) as a slot sceneSvg fills in.
const DELAY_SLOT = /\{\{(-?[\d.]+)\}\}/g
function withDelaySlot(anim: string): string {
  let times = 0
  let hasDelay = false
  const parts = anim
    .trim()
    .split(/\s+/)
    .map(p => {
      if (!/^-?[\d.]+s$/.test(p) || ++times !== 2) return p
      hasDelay = true
      return `{{${parseFloat(p)}}}`
    })
  if (!hasDelay) parts.push('{{0}}')
  return parts.join(' ')
}

class Frame {
  // Absent: the frame is drawn as CSS animations rather than posed at a time.
  readonly t: number | undefined
  readonly used = new Set<string>()
  constructor(t?: number) {
    this.t = t
  }
  // A group posed by `anim` at this frame, placed at (x, y); `origin` is where it scales from.
  g(anim: string | null, inner: string, x = 0, y = 0, origin: [number, number] = [0, 0]): string {
    let body = inner
    if (anim && this.t === undefined) {
      this.used.add(anim.trim().split(/\s+/)[0] ?? '')
      body = `<g style="animation:${withDelaySlot(anim)};transform-origin:${origin[0]}px ${origin[1]}px">${inner}</g>`
    } else if (anim) {
      const p = poseAt(anim, this.t ?? 0)
      if (p) {
        if (p.o <= 0.02) return ''
        const tf: string[] = []
        if (p.tx || p.ty) tf.push(`translate(${n2(p.tx)} ${n2(p.ty)})`)
        if (p.sx !== 1 || p.sy !== 1) {
          tf.push(`translate(${origin[0]} ${origin[1]}) scale(${n2(p.sx) || 0.001} ${n2(p.sy) || 0.001}) translate(${-origin[0]} ${-origin[1]})`)
        }
        const attrs = (tf.length ? ` transform="${tf.join(' ')}"` : '') + (p.o < 1 ? ` opacity="${n2(p.o)}"` : '')
        if (attrs) body = `<g${attrs}>${inner}</g>`
      }
    }
    return x || y ? `<g transform="translate(${x} ${y})">${body}</g>` : body
  }
  // Shows sub-scene i of n for its slice of a T-second cycle, building only the one on screen.
  cycle(scenes: (() => string)[], T: number): string {
    const n = scenes.length
    if (this.t === undefined) {
      return scenes.map((scene, i) => this.g(`vis${n} ${T}s step-end infinite ${n2(i * (T / n) - T)}s`, scene())).join('')
    }
    const i = Math.floor((((this.t % T) + T) % T) / (T / n))
    return scenes[i]!()
  }

  // The @keyframes of every track this frame's groups name.
  css(): string {
    return [...this.used]
      .map(name => {
        const track = KF[name] ?? (name.startsWith('vis') ? visTrack(Number(name.slice(3))) : undefined)
        return track ? keyframesCss(name, track) : ''
      })
      .join('')
  }
}

// ---------- the mascot ----------

type Eyes = 'normal' | 'look' | 'lookL' | 'lookR' | 'down' | 'focus' | 'happy' | 'shades' | 'closed' | 'scan'
type ClawdOpts = {
  eyes?: Eyes
  bob?: string | null
  armL?: string | null
  armR?: string | null
  armLUp?: boolean
  armRUp?: boolean
  walk?: boolean
  sit?: boolean
  extra?: string
}

function eyes(f: Frame, kind: Eyes): string {
  const pair = rect(4, 1, 1, 2, 'e') + rect(11, 1, 1, 2, 'e')
  switch (kind) {
    case 'normal':
      return f.g('blink 4s step-end infinite', pair)
    case 'look':
      return f.g('look 8s step-end infinite', pair)
    case 'scan':
      return f.g('scan .9s step-end infinite', pair)
    case 'lookL':
      return f.g('blink 3.5s step-end infinite', rect(3, 1, 1, 2, 'e') + rect(10, 1, 1, 2, 'e'))
    case 'lookR':
      return f.g('blink 3.1s step-end infinite', rect(5, 1, 1, 2, 'e') + rect(12, 1, 1, 2, 'e'))
    case 'down':
      return rect(3, 2, 1, 2, 'e') + rect(10, 2, 1, 2, 'e')
    case 'focus':
      return rect(3, 2, 2, 1, 'e') + rect(10, 2, 2, 1, 'e') + rect(3, 1, 2, 1, 'O') + rect(10, 1, 2, 1, 'O')
    case 'happy':
      return spr(['.e......e.', 'e.e....e.e'], 3, 1)
    case 'closed':
      return rect(3, 2, 2, 1, 'e') + rect(10, 2, 2, 1, 'e')
    case 'shades':
      return spr(['kkkkk.kkkkk', 'kkkkkkkkkkk', '.kkk...kkk.'], 2, 1) + rect(3, 1, 1, 1, 'w') + rect(9, 1, 1, 1, 'w')
  }
}

// 16x8: body 12x6, arms 2x2 at the sides, four 1x2 legs.
function clawd(f: Frame, x: number, y: number, o: ClawdOpts = {}): string {
  const body = rect(2, 0, 12, 6, 'o') + rect(2, 5, 12, 1, 'O')
  const armL = f.g(o.armL ?? null, o.armLUp ? rect(0, 0, 2, 2, 'o') + rect(1, 2, 1, 1, 'o') : rect(0, 2, 2, 2, 'o'))
  const armR = f.g(o.armR ?? null, o.armRUp ? rect(14, 0, 2, 2, 'o') + rect(14, 2, 1, 1, 'o') : rect(14, 2, 2, 2, 'o'))
  let legs = ''
  if (!o.sit) {
    const a = rect(3, 6, 1, 2, 'o') + rect(10, 6, 1, 2, 'o')
    const c = rect(5, 6, 1, 2, 'o') + rect(12, 6, 1, 2, 'o')
    legs = o.walk ? f.g('bob .3s step-end infinite', a) + f.g('bob .3s step-end infinite -.15s', c) : a + c
  }
  return f.g(o.bob ?? null, legs + body + armL + armR + eyes(f, o.eyes ?? 'normal') + (o.extra ?? ''), x, y)
}

// 8x5 helper mascot.
function mini(f: Frame, x: number, y: number, carry = '', walk = true): string {
  const body = rect(1, 0, 6, 3, 'o') + rect(0, 1, 1, 1, 'o') + rect(7, 1, 1, 1, 'o') + rect(2, 1, 1, 1, 'e') + rect(5, 1, 1, 1, 'e')
  const la = rect(2, 3, 1, 2, 'o')
  const lb = rect(5, 3, 1, 2, 'o')
  const legs = walk ? f.g('bob .3s step-end infinite', la) + f.g('bob .3s step-end infinite -.15s', lb) : la + lb
  return `<g transform="translate(${x} ${y})">${legs}${body}${carry}</g>`
}

const SPARK = ['.y.', 'yyy', '.y.']
const sparkle = (f: Frame, x: number, y: number, d: number, dur = 1.6) => f.g(`tw ${dur}s step-end infinite ${-d}s`, spr(SPARK), x, y)

const BANG = ['.wwww.', 'ww.www', 'ww.www', 'wwwwww', 'ww.www', '.wwww.', '.w....']
const BOX = ['BbbbB', 'bbYbb', 'bbbbb', 'BbbbB']
const SUN = ['..hhhh..', '.hhhhhh.', 'hhyyyyhh', 'hyyyyyyh', 'hyyyyyyh']

// A horizontally banded backdrop for the right of the band, its left edge dithered.
function backdrop(bands: [string, number][], x0 = 30): string {
  let out = ''
  let y = 0
  for (const [c, h] of bands) {
    for (let j = 0; j < h; j++, y++) {
      out += rect(x0 + 4, y, W - x0 - 4, 1, c)
      for (let dx = 0; dx < 4; dx++) {
        const xx = x0 + dx
        const on = dx === 3 ? (xx + y) % 4 !== 1 : dx === 2 ? (xx + y) % 2 === 0 : dx === 1 ? (xx + y) % 4 === 0 : false
        if (on) out += rect(xx, y, 1, 1, c)
      }
    }
  }
  return out
}

// The dotted field that fades in from the left, as in the band's art.
function dots(f: Frame): string {
  let out = ''
  for (let x = 0; x < W; x += 2) {
    for (let y = 1; y < H; y += 2) {
      const r = rnd(x * 31 + y)
      const p = Math.pow(x / W, 1.6) * 0.6
      if (r < p) {
        out += r < p * 0.12
          ? f.g(`tw ${(2 + rnd(x + y * 7) * 3).toFixed(2)}s step-end infinite ${(-rnd(x * y + 1) * 4).toFixed(2)}s`, rect(x, y, 1, 1, '#555'))
          : rect(x, y, 1, 1, r < p * 0.35 ? '#3c3c3c' : '#2c2c2c')
      }
    }
  }
  return out
}

const stars = (f: Frame, n: number, seed: number) =>
  Array.from({ length: n }, (_, i) => {
    const x = 36 + Math.floor(rnd(seed + i * 4.3) * 62)
    const y = Math.floor(rnd(seed + i * 8.9) * 8)
    return f.g(`tw ${(1.5 + rnd(i + seed) * 2).toFixed(2)}s step-end infinite -${(rnd(i * 2 + seed) * 2).toFixed(2)}s`, rect(x, y, 1, 1, 'w'))
  }).join('')

const palm = (x: number) =>
  rect(x, 4, 2, 14, 'b') + rect(x, 6, 2, 1, 'B') + rect(x, 10, 2, 1, 'B') + spr(['.nnn.nnn.', 'nnNnnnNnn', 'n..nNn..n', '...yny...'], x - 3, 1)

// ---------- idle: sweeping, walking, phone, chatting, reading ----------

function idle(f: Frame): string {
  const sweeping = () =>
    clawd(f, 60, 10, { bob: 'bob 1.2s step-end infinite' }) +
    f.g('sweep .6s step-end infinite', rect(76, 4, 1, 11, 't') + rect(75, 14, 4, 1, 'B') + spr(['YYYYY', 'YyYyY', 'Y.Y.Y'], 74, 15)) +
    [0, 0.4, 0.8].map((d, i) => f.g(`dust 1.2s linear infinite ${-d}s`, rect(0, 0, 1 + (i % 2), 1, 'g'), 73, 16 - i)).join('') +
    sparkle(f, 86, 3, 0) + sparkle(f, 92, 9, 0.6) + sparkle(f, 83, 12, 1.1) +
    f.g('tw 1.2s step-end infinite -.3s', spr(['yyy', '.y.']), 90, 1)

  const walking = () => {
    const butterfly = f.g('on .3s step-end infinite', spr(['v.v', '.k.'])) + f.g('off .3s step-end infinite', spr(['...', 'vkv']))
    return (
      f.g('walk 8s steps(18) infinite', clawd(f, 70, 10, { walk: true, eyes: 'look' })) +
      f.g('walk 8s steps(18) infinite -.5s', f.g('bob .9s step-end infinite', butterfly), 82, 4)
    )
  }

  const phone = () =>
    clawd(f, 66, 10, { eyes: 'down', bob: 'bob 2.4s step-end infinite' }) +
    spr(['KKKK', 'KccK', 'KccK', 'KccK', 'KKKK'], 62, 9) +
    f.g('on .6s step-end infinite', rect(63, 10, 2, 1, 'w') + rect(63, 12, 1, 1, 'w')) +
    f.g('off .6s step-end infinite', rect(63, 11, 2, 1, 'w') + rect(64, 13, 1, 1, 'w')) +
    f.g('rise 2.4s linear infinite', spr(['p.p', 'ppp', '.p.']), 60, 6) +
    f.g('rise 2.4s linear infinite -1.2s', spr(['y', 'y', '.', 'y']), 64, 5) +
    f.g('rise 2.4s linear infinite -.6s', spr(['nnn', 'n.n', 'nnn']), 56, 7)

  const chatting = () =>
    clawd(f, 40, 10, { eyes: 'lookR', bob: 'bob .6s step-end infinite', armR: 'wave 1.2s step-end infinite' }) +
    clawd(f, 64, 10, { eyes: 'lookL', bob: 'bob .6s step-end infinite -.3s', armL: 'wave 1.2s step-end infinite -.6s' }) +
    f.g('on 2.4s step-end infinite', spr(['.wwwwwww.', 'wwwwwwwww', 'wwKwKwKww', 'wwwwwwwww', '.wwwwwww.', '..ww.....', '..w......'], 48, 1)) +
    f.g('off 2.4s step-end infinite', spr(['.wwwwwww.', 'wwwpwpwww', 'wwwpppwww', 'wwwwpwwww', '.wwwwwww.', '.....ww..', '......w..'], 60, 1)) +
    f.g('tw 4.8s step-end infinite -2s', spr(['y.y', '.y.', 'y.y']), 58, 9)

  const reading = () =>
    clawd(f, 64, 10, { eyes: 'down', bob: 'bob 3s step-end infinite' }) +
    spr(['UwwwwUwwwwU', 'UwgggUwgggU', 'UwwwwUwwwwU', 'UwgggUwggwU', 'UUUUUUUUUUU'], 55, 11) +
    f.g('flip 3s step-end infinite', spr(['wwww', 'wggw', 'wwww', 'wgww']), 61, 11) +
    f.g('tw 3s step-end infinite -1s', spr(['.y.', 'yyy', 'yyy', '.w.']), 80, 3)

  return f.cycle([sweeping, walking, phone, chatting, reading], 40)
}

// ---------- working: laptop, papers, delegating, boxes, office, analysis ----------

function working(f: Frame): string {
  const typing = () => {
    const lines = [4, 6, 3, 5]
      .map((w, i) => f.g(`grow 1.6s steps(${w}) infinite ${-i * 0.4}s`, rect(54, 9 + i, w, 1, i % 2 ? 'c' : 'n'), 0, 0, [54, 9 + i]))
      .join('')
    const laptop = f.g('pull 6s steps(3) infinite', rect(52, 8, 10, 6, 'L') + rect(53, 8, 8, 5, 'k') + lines + rect(50, 14, 14, 1, 'l') + rect(51, 15, 12, 1, 'L'))
    const bits = [0, 0.5, 1, 1.5].map((d, i) => f.g(`rise 2s linear infinite ${-d}s`, i % 2 ? spr(['n', 'n', 'n']) : spr(['nn', 'nn', 'nn']), 54 + i * 2, 6)).join('')
    return laptop + bits + clawd(f, 64, 10, { eyes: 'focus', bob: 'bob .6s step-end infinite', armL: 'bob .3s step-end infinite', armR: 'bob .3s step-end infinite -.15s' })
  }

  const papers = () => {
    const sheet = spr(['PPP', 'PgP', 'PPP', 'PgP'])
    return (
      spr(['PPPPPP', 'PggggP', 'PPPPPP', 'PgggPP', 'PPPPPP', 'PggggP'], 50, 12) +
      [0, 0.5, 1].map(d => f.g(`fly 1.5s steps(7) infinite ${-d}s`, sheet, 52, 10)).join('') +
      clawd(f, 66, 10, { eyes: 'scan' }) +
      f.g('bob 1.2s step-end infinite', spr(['PPPP', 'PggP', 'PPPP', 'PgPP', 'PPPP']), 63, 11) +
      f.g('tw 2s step-end infinite', spr(['y', 'y', '.', 'y']), 72, 5)
    )
  }

  const delegate = () => {
    const box = rect(2, -2, 4, 2, 'b') + rect(3, -2, 2, 1, 'Y')
    const doc = rect(2, -3, 3, 3, 'P') + rect(3, -2, 1, 1, 'g')
    return (
      clawd(f, 74, 10, { armLUp: true, armL: 'wave .6s step-end infinite' }) +
      spr(BANG, 66, 2) +
      [0, 2, 4].map((d, i) => f.g(`dispatch 6s steps(24) infinite ${-d}s`, mini(f, 0, 0, i === 1 ? doc : box), 66, 13)).join('')
    )
  }

  const boxes = () =>
    spr(BOX, 32, 14) + spr(BOX, 38, 14) + spr(BOX, 35, 10) + spr(BOX, 86, 14) + spr(BOX, 92, 14) +
    f.g('off 6s step-end infinite', spr(BOX, 41, 10)) +
    f.g('carry 6s steps(24) infinite',
      clawd(f, 66, 10, { walk: true, armLUp: true, armRUp: true, extra: f.g('on 6s step-end infinite', spr(BOX, 5, -4)) }))

  const office = () =>
    [28, 43, 58].map((x, i) =>
      f.g(`bob .3s step-end infinite ${-i * 0.15}s`, mini(f, x, 13, '', false)) +
      spr(['LLLLL', 'LkkkL', 'LkkkL', 'LLLLL', '..L..'], x + 8, 9) +
      f.g(`on .6s step-end infinite ${-i * 0.3}s`, rect(x + 9, 10, 2, 1, 'n') + rect(x + 9, 11, 3, 1, 'c')) +
      f.g(`off .6s step-end infinite ${-i * 0.3}s`, rect(x + 9, 10, 3, 1, 'c') + rect(x + 10, 11, 2, 1, 'n')) +
      rect(x + 7, 14, 7, 1, 'b') + rect(x + 8, 15, 1, 3, 'B') + rect(x + 12, 15, 1, 3, 'B'),
    ).join('') +
    f.g('pace 4s steps(6) infinite', clawd(f, 80, 10, { walk: true, armLUp: true, armL: 'wave .6s step-end infinite' })) +
    f.g('tw 2s step-end infinite', spr(BANG), 86, 1)

  const analyze = () =>
    rect(36, 2, 22, 13, 'L') + rect(37, 3, 20, 11, 'k') + rect(45, 15, 4, 2, 'L') + rect(42, 17, 10, 1, 'L') +
    [2, 5, 3, 7, 4, 8]
      .map((h, i) => f.g(`growY 3s steps(${h}) infinite ${-i * 0.3}s`, rect(39 + i * 3, 13 - h, 2, h, i % 2 ? 'c' : 'n'), 0, 0, [40 + i * 3, 13]))
      .join('') +
    clawd(f, 68, 10, { eyes: 'focus', armLUp: true }) +
    f.g('magscan 5s steps(10) infinite', spr(['.lll...', 'lcccl..', 'lcccl..', 'lcccl..', '.lllb..', '....bb.', '.....bb']), 58, 5) +
    f.g('tw 5s step-end infinite', spr(['www', '..w', '.ww', '...', '.w.']), 78, 1)

  return f.cycle([typing, papers, delegate, boxes, office, analyze], 36)
}

// ---------- task complete: one burst of confetti, jumping and dancing ----------

export const DONE_SECONDS = 6.5

function done(f: Frame): string {
  const colors = ['r', 'y', 'c', 'n', 'p', 'v', 'f', 'u']
  let confetti = ''
  for (let i = 0; i < 34; i++) {
    const x = 26 + Math.floor(rnd(i * 3.7) * 72)
    const dur = (1.6 + rnd(i * 5.1) * 1.2).toFixed(2)
    const d = (rnd(i * 9.3) * 1.2).toFixed(2)
    const c = colors[i % colors.length]
    const piece =
      f.g(`on ${(0.3 + Math.round(rnd(i) * 2) * 0.15).toFixed(2)}s step-end infinite`, rnd(i) > 0.5 ? rect(0, 0, 1, 2, c) : rect(0, 0, 2, 1, c)) +
      f.g(`off ${(0.3 + Math.round(rnd(i) * 2) * 0.15).toFixed(2)}s step-end infinite`, rect(0, 0, 1, 1, colors[(i + 3) % colors.length]))
    confetti += f.g(`fall ${dur}s steps(12) ${d}s 2 both`, piece, x, 0)
  }
  return (
    confetti +
    f.g('dance 2.4s step-end 0s 2 forwards', clawd(f, 66, 10, { eyes: 'happy', armL: 'wave .3s step-end infinite', armR: 'wave .3s step-end infinite -.15s', walk: true })) +
    f.g('hop .6s step-end 0s 9', mini(f, 52, 13, '', false)) +
    f.g('hop .6s step-end -.3s 9', mini(f, 86, 13, '', false)) +
    sparkle(f, 60, 2, 0, 0.9) + sparkle(f, 88, 4, 0.45, 0.9) + sparkle(f, 46, 6, 0.3, 0.9)
  )
}

// ---------- relaxing: sunset chair, fishing, hammock, campfire, barbecue, sunset drive ----------

function relax(f: Frame): string {
  const sunset = () =>
    backdrop([['s', 3], ['m', 3], ['d', 3], ['f', 3], ['U', 3], ['t', 3]]) +
    f.g('sink 8s steps(3) infinite', spr(SUN), 76, 7) +
    rect(34, 12, 66, 3, 'U') +
    [0, 0.4, 0.8, 1.2].map((d, i) => f.g(`tw 1.6s step-end infinite ${-d}s`, rect(0, 0, 2 + (i % 2), 1, 'h'), 72 + i * 4, 12 + (i % 3))).join('') +
    f.g('drift 16s linear infinite', spr(['K.K', '.K.']) + spr(['K.K', '.K.'], 5, 2), 96, 2) +
    spr(['r......', 'wr.....', 'rwr....', 'wrwrwrw', 'b.....b', 'b.....b'], 46, 10) +
    clawd(f, 46, 8, { eyes: 'shades', bob: 'bob 3s step-end infinite' }) +
    spr(['..p..', '.ppp.', '..t..', 'cccc.', 'cccc.', '.cc..'], 63, 10) +
    f.g('riseR 3s linear infinite', spr(['.ww', '.w.', 'ww.']), 58, 5) +
    f.g('riseR 3s linear infinite -1.5s', spr(['ww', 'w.', 'w.']), 52, 5)

  const fishing = () =>
    backdrop([['V', 4], ['s', 4], ['V', 3], ['U', 7]]) +
    stars(f, 14, 3) +
    spr(['.ww.', 'wwww', 'wwww', '.ww.'], 90, 1) +
    [0, 1, 2].map(i => f.g(`tw 2s step-end infinite ${-i * 0.6}s`, rect(0, 0, 3, 1, 'u'), 40 + i * 15, 13 + i)).join('') +
    rect(38, 10, 26, 2, 'b') + rect(38, 10, 26, 1, 't') + rect(40, 12, 1, 6, 'B') + rect(60, 12, 1, 6, 'B') +
    clawd(f, 46, 4, { eyes: 'closed', bob: 'bob 3s step-end infinite' }) +
    spr(['.......t', '......t.', '.....t..', '....t...', '...t....', '..t.....', '.t......'], 60, 0) +
    rect(68, 1, 1, 12, 'g') +
    f.g('bob 1.2s step-end infinite', rect(67, 12, 3, 1, 'r') + rect(67, 13, 3, 1, 'w')) +
    f.g('leap 8s steps(10) infinite', spr(['.uu.u', 'uuuuu', '.uu.u']), 86, 13)

  const hammockScene = () => {
    // The hammock sags between the palms: tied high at the trunks, lowest in the middle.
    let hammock = ''
    for (let x = 48; x <= 82; x++) {
      const t = (x - 65) / 17
      hammock += rect(x, Math.round(9 + 4 * (1 - t * t)), 1, 1, x % 3 ? 'w' : 'r')
    }
    return (
      backdrop([['C', 11], ['c', 2], ['t', 5]]) +
      palm(46) + palm(83) +
      f.g('swing 3s step-end infinite', clawd(f, 57, 7, { eyes: 'closed', sit: true }) + hammock) +
      f.g('riseR 3s linear infinite', spr(['www', '.w.', 'www']), 70, 2) +
      f.g('riseR 3s linear infinite -1.5s', spr(['ww', 'ww']), 74, 3)
    )
  }

  const campfire = () =>
    backdrop([['V', 5], ['s', 5], ['m', 2], ['N', 6]]) +
    stars(f, 12, 11) +
    f.g('on .3s step-end infinite', spr(['..r...', '.rfr..', '.rfyr.', 'rfyyfr']), 70, 10) +
    f.g('off .3s step-end infinite', spr(['...r..', '..rfr.', '.ryfr.', 'rfyyfr']), 70, 10) +
    spr(['BB..BB', '.BBBB.', 'BB..BB'], 70, 14) +
    [0, 0.7, 1.4].map((d, i) => f.g(`rise 2.1s linear infinite ${-d}s`, rect(0, 0, 1, 1, 'h'), 71 + i * 2, 8)).join('') +
    f.g('on .6s step-end infinite', rect(64, 16, 18, 1, 'O')) +
    rect(46, 15, 14, 3, 'B') +
    clawd(f, 47, 9, { eyes: 'closed', bob: 'bob 3.6s step-end infinite' }) +
    spr(['www.', 'wwwP', 'www.'], 61, 12) +
    f.g('rise 2.4s linear infinite', spr(['g', '.', 'g']), 62, 9) +
    f.g('rise 2.4s linear infinite -1.2s', spr(['g', 'g']), 63, 9)

  const barbecue = () => {
    let fence = ''
    for (let x = 35; x < W; x += 3) fence += rect(x, 7, 2, 6, 'w')
    return (
      backdrop([['C', 13], ['n', 2], ['N', 3]]) +
      fence + rect(34, 9, 66, 1, 'w') +
      spr(['KKKKKKKKKKKK', '.GGGGGGGGGG.', '..GGGGGGGG..', '...G....G...', '...G....G...', '..GG....GG..'], 46, 11) +
      f.g('on .6s step-end infinite', rect(49, 12, 6, 1, 'd') + rect(56, 12, 1, 1, 'f')) +
      f.g('off .6s step-end infinite', rect(48, 12, 2, 1, 'f') + rect(51, 12, 6, 1, 'd')) +
      f.g('flipfood 2s steps(4) infinite', rect(47, 10, 3, 1, 'B')) +
      rect(51, 10, 3, 1, 'r') +
      f.g('flipfood 2s steps(4) infinite -1s', rect(55, 10, 2, 1, 'B')) +
      [0, 0.8, 1.6].map((d, i) => f.g(`rise 2.4s linear infinite ${-d}s`, spr(['g.', '.g']), 48 + i * 3, 6)).join('') +
      clawd(f, 64, 10, { eyes: 'happy', extra: spr(['.wwwwww.', 'wwwwwwww', '.wwwwww.'], 4, -3) }) +
      f.g('wave .6s step-end infinite', rect(60, 11, 4, 1, 't') + rect(58, 10, 2, 2, 'l'))
    )
  }

  const drive = () => {
    const palmSmall = rect(0, 4, 1, 8, 'B') + spr(['.N.N.', 'NNNNN', 'N.N.N'], -2, 2)
    let dashes = ''
    for (let x = 40; x < W + 8; x += 8) dashes += rect(x, 16, 4, 1, 'y')
    const car = spr([
      '.................c....',
      '.................c....',
      'rrrrrrrrrrrrrrrrrrrrrr',
      'rrrrrrrrrrrrrrrrrrrrhh',
      'RRRRRRRRRRRRRRRRRRRRRR',
    ])
    const wheels =
      spr(['.KKK............KKK...', '.KKK............KKK...'], 0, 5) +
      f.g('on .3s step-end infinite', rect(2, 5, 1, 1, 'g') + rect(18, 5, 1, 1, 'g')) +
      f.g('off .3s step-end infinite', rect(2, 6, 1, 1, 'g') + rect(18, 6, 1, 1, 'g'))
    return (
      backdrop([['s', 3], ['m', 3], ['d', 3], ['f', 3], ['N', 2], ['G', 4]]) +
      spr(SUN, 74, 8) + rect(34, 12, 66, 2, 'N') + rect(34, 14, 66, 4, 'G') +
      f.g('dash .6s steps(4) infinite', dashes) +
      f.g('zoom 2.4s steps(24) infinite', palmSmall, 100, 0) +
      f.g('zoom 2.4s steps(24) infinite -1.2s', palmSmall, 100, 0) +
      f.g('drift 16s linear infinite', spr(['K.K', '.K.']), 96, 2) +
      f.g('bob .6s step-end infinite', clawd(f, 48, 6, { eyes: 'shades', sit: true, armRUp: true, armR: 'wave 1.2s step-end infinite' }) + `<g transform="translate(46 9)">${car}${wheels}</g>`) +
      [0, 0.3].map(d => f.g(`dust .6s linear infinite ${-d}s`, rect(0, 0, 2, 1, 'g'), 45, 13)).join('')
    )
  }

  return f.cycle([sunset, fishing, hammockScene, campfire, barbecue, drive], 48)
}

function draw(mood: Mood, f: Frame): string {
  const body = mood === 'working' ? working(f) : mood === 'done' ? done(f) : mood === 'relax' ? relax(f) : idle(f)
  const field = dots(f)
  const style = f.t === undefined ? `<style>${f.css()}</style>` : ''
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="${W * 3}" height="${H * 3}" shape-rendering="crispEdges">` +
    `${style}<rect x="-2" y="-2" width="${W + 4}" height="${H + 4}" fill="${BAND_BG}"/>${field}${body}</svg>`
  )
}

const animated = new Map<Mood, string>()
// `mood` animated by the browser, starting `t` seconds in: every delay is moved back
// by `t`, so the drawing a redraw reloads carries on from where the last one was.
export function sceneSvg(mood: Mood, t = 0): string {
  let svg = animated.get(mood)
  if (!svg) animated.set(mood, (svg = draw(mood, new Frame())))
  return svg.replace(DELAY_SLOT, (_, d: string) => `${n2(parseFloat(d) - t)}s`)
}

// One still frame of `mood`, `t` seconds after it began.
export function sceneFrameSvg(mood: Mood, t: number): string {
  return draw(mood, new Frame(t))
}

export const SCENE_WIDTH = W * 3
export const SCENE_HEIGHT = H * 3

